def heuristic(state):
    goal=(1,2,3,4,5,6,7,8,0)
    total=0
    for i,x in enumerate(state):
        if x:
            j=goal.index(x); total += abs(i//3-j//3)+abs(i%3-j%3)
    conflicts=0
    for row in range(3):
        vals=[]
        for col in range(3):
            x=state[3*row+col]
            if x and goal.index(x)//3==row: vals.append(goal.index(x)%3)
        conflicts += sum(vals[i]>vals[j] for i in range(len(vals)) for j in range(i+1,len(vals)))
    for col in range(3):
        vals=[]
        for row in range(3):
            x=state[3*row+col]
            if x and goal.index(x)%3==col: vals.append(goal.index(x)//3)
        conflicts += sum(vals[i]>vals[j] for i in range(len(vals)) for j in range(i+1,len(vals)))
    return float(total + 2*conflicts)

def heuristic(state):
    goal=(1,2,3,4,5,6,7,8,0)
    m=0
    for i,x in enumerate(state):
        if x:
            j=goal.index(x); m += abs(i//3-j//3)+abs(i%3-j%3)
    misplaced=sum(1 for i,x in enumerate(state) if x and x != goal[i])
    return 0.608679742693*m + 0.197557060308*misplaced + 0.193763196999*0.0
